# Script to build all 10 OOPS topics (30 questions each: 10 Easy, 10 Medium, 10 Hard)
import json

def q(text, options, correct, explanation, diff):
    assert len(options) == 4, f"Options length != 4: {text}"
    assert correct in options, f"Correct '{correct}' not in options {options} for {text}"
    assert diff in ("Easy", "Medium", "Hard"), f"Invalid diff: {diff}"
    return {
        "question": text,
        "options": options,
        "correct_answer": correct,
        "explanation": explanation,
        "difficulty": diff
    }

